INSERT INTO ai_call_record VALUES(1000, '13800138001', '张先生', '广东省广州市天河区珠江新城', '2026-03-14 09:15:30', '2026-03-14 09:23:45', 495, 102, 1, '咨询劳动合同解除相关法律问题，公司拖欠工资3个月', '根据《劳动合同法》第三十八条规定，用人单位未及时足额支付劳动报酬的，劳动者可以解除劳动合同，并要求经济补偿。', '1', null, null, 'admin', '2026-03-14 09:15:30', '', null, '');
INSERT INTO ai_call_record VALUES(1001, '13900139002', '李女士', '广东省深圳市南山区科技园', '2026-03-14 09:30:20', '2026-03-14 09:42:35', 735, 103, 2, '咨询离婚财产分割问题，婚前房产婚后共同还贷如何分配', '婚前一方付首付并登记在自己名下的房产，婚后共同还贷部分及增值部分属于夫妻共同财产，离婚时应予分割。', '1', null, null, 'admin', '2026-03-14 09:30:20', '', null, '');
INSERT INTO ai_call_record VALUES(1002, '13600136003', '王先生', '广东省珠海市香洲区吉大', '2026-03-14 10:05:10', '2026-03-14 10:15:40', 630, 104, 3, '咨询继承纠纷，父母去世后房产继承分配问题', '根据《民法典》继承编，没有遗嘱的按法定继承办理，第一顺序继承人为配偶、子女、父母，一般均等分配。', '1', null, null, 'admin', '2026-03-14 10:05:10', '', null, '');
INSERT INTO ai_call_record VALUES(1003, '13700137004', '赵女士', '广东省佛山市禅城区祖庙', '2026-03-14 10:20:00', '2026-03-14 10:30:20', 620, 105, 4, '咨询交通事故人身损害赔偿标准', '根据《民法典》侵权责任编，人身损害赔偿包括医疗费、护理费、误工费等，构成伤残的还包括残疾赔偿金。', '1', null, null, 'admin', '2026-03-14 10:20:00', '', null, '');
INSERT INTO ai_call_record VALUES(1004, '13500135005', '钱先生', '广东省东莞市莞城区', '2026-03-14 10:45:30', '2026-03-14 10:55:15', 585, 106, 5, '咨询商标被侵权如何维权', '建议收集侵权证据，发送律师函要求停止侵权，必要时向人民法院起诉索赔。', '1', null, null, 'admin', '2026-03-14 10:45:30', '', null, '');
INSERT INTO ai_call_record VALUES(1005, '18800188006', '孙女士', '广东省广州市越秀区北京路', '2026-03-14 11:00:00', '2026-03-14 11:12:30', 750, 107, 6, '咨询房屋租赁合同纠纷，房东不退押金', '根据《民法典》合同编，租赁合同到期后出租人应在合理期限内退还押金，无正当理由扣留的，承租人可以起诉。', '1', null, null, 'admin', '2026-03-14 11:00:00', '', null, '');
INSERT INTO ai_call_record VALUES(1006, '18600186007', '周先生', '广东省中山市石岐区', '2026-03-14 11:15:20', '2026-03-14 11:28:45', 805, 109, 7, '咨询民间借贷纠纷，借款人不还款', '建议收集借条、转账记录等证据，先协商解决，协商不成可向人民法院提起诉讼，注意诉讼时效为3年。', '1', null, null, 'admin', '2026-03-14 11:15:20', '', null, '');
INSERT INTO ai_call_record VALUES(1007, '15800158008', '吴女士', '广东省惠州市惠城区', '2026-03-14 11:30:00', '2026-03-14 11:38:20', 500, 102, 1, '咨询工伤认定及赔偿标准', '建议先申请工伤认定，认定后再做劳动能力鉴定，根据伤残等级计算赔偿金额，包括医疗费、停工留薪期工资等。', '1', null, null, 'admin', '2026-03-14 11:30:00', '', null, '');
INSERT INTO ai_call_record VALUES(1008, '15900159009', '郑先生', '广东省江门市蓬江区', '2026-03-14 13:30:00', '2026-03-14 13:42:10', 730, 103, 2, '咨询消费者权益保护，网购商品质量问题索赔', '根据《消费者权益保护法》，经营者提供商品有欺诈行为的，消费者可要求三倍赔偿，最低500元。', '1', null, null, 'admin', '2026-03-14 13:30:00', '', null, '');
INSERT INTO ai_call_record VALUES(1009, '18200182010', '冯女士', '广东省广州市番禺区市桥', '2026-03-14 13:50:30', '2026-03-14 14:05:20', 890, 104, 3, '咨询离婚后子女抚养权变更条件', '根据《民法典》婚姻家庭编，具有抚养权一方不尽抚养义务或有虐待行为的，另一方可以请求变更抚养权。', '1', null, null, 'admin', '2026-03-14 13:50:30', '', null, '');
INSERT INTO ai_call_record VALUES(1010, '13300133011', '陈先生', '广东省深圳市福田区', '2026-03-14 14:10:00', '2026-03-14 14:20:30', 630, 106, 5, '咨询专利侵权纠纷处理流程', '建议先进行专利侵权比对分析，确认侵权后可发送律师函或直接起诉，可申请诉前禁令和证据保全。', '1', null, null, 'admin', '2026-03-14 14:10:00', '', null, '');
INSERT INTO ai_call_record VALUES(1011, '15300153012', '林女士', '广东省汕头市金平区', '2026-03-14 14:30:00', '2026-03-14 14:45:20', 920, 109, 8, '咨询房产买卖合同纠纷，卖方违约', '根据《民法典》合同编，卖方违约的，买方可以要求继续履行或解除合同并主张违约金和赔偿损失。', '1', null, null, 'admin', '2026-03-14 14:30:00', '', null, '');
INSERT INTO ai_call_record VALUES(1012, '18100181013', '黄先生', '广东省湛江市霞山区', '2026-03-14 14:50:00', '2026-03-14 15:00:15', 615, 102, 1, '咨询劳动仲裁流程和时限', '劳动争议申请仲裁的时效为1年，自知道或应当知道权利被侵害之日起计算，仲裁是劳动争议的前置程序。', '1', null, null, 'admin', '2026-03-14 14:50:00', '', null, '');
INSERT INTO ai_call_record VALUES(1013, '15000150014', '何女士', '广东省茂名市茂南区', '2026-03-14 15:10:00', '2026-03-14 15:22:30', 750, 103, 2, '咨询婚前财产公证办理流程', '双方携带身份证、户口本、房产证等到公证处办理，公证员会对财产归属进行确认并出具公证书。', '1', null, null, 'admin', '2026-03-14 15:10:00', '', null, '');
INSERT INTO ai_call_record VALUES(1014, '17600176015', '罗先生', '广东省肇庆市端州区', '2026-03-14 15:30:00', '2026-03-14 15:40:20', 620, 104, 3, '咨询离婚诉讼中房产如何评估分割', '诉讼中可申请法院委托有资质的评估机构进行房产评估，按评估价值进行分割。', '1', null, null, 'admin', '2026-03-14 15:30:00', '', null, '');
INSERT INTO ai_call_record VALUES(1015, '13100131016', '梁女士', '广东省广州市白云区', '2026-03-14 15:50:00', '2026-03-14 16:05:30', 930, 105, 4, '咨询医疗事故损害赔偿', '建议先申请医疗事故技术鉴定，确认是否构成医疗事故，再根据伤残等级计算赔偿金额。', '1', null, null, 'admin', '2026-03-14 15:50:00', '', null, '');
