INSERT INTO ai_call_record VALUES(1018, '17700177019', '韩先生', '广东省韶关市武江区', '2026-03-14 16:40:00', '2026-03-14 16:52:20', 740, 102, 1, '咨询经济补偿金计算方法', '根据《劳动合同法》第四十七条，经济补偿按工作年限计算，每满一年支付一个月工资，月工资指离职前12个月的平均工资。', '1', null, null, 'admin', '2026-03-14 16:40:00', '', null, '');
INSERT INTO ai_call_record VALUES(1019, '13200132020', '唐女士', '广东省揭阳市榕城区', '2026-03-14 17:00:00', '2026-03-14 17:08:30', 510, 103, 2, '咨询家庭暴力如何申请人身安全保护令', '遭受家庭暴力或面临家庭暴力现实危险的，可向人民法院申请 人身安全保护令，需提供遭受家暴的证据。', '1', null, null, 'admin', '2026-03-14 17:00:00', '', null, '');
